  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fabricant-De-Pi&#232;ges-(Roublard).html&quot; title=&quot;Fabricant de pi&#232;ges&quot;&gt;Fabricant de pi&#232;ges&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;F&#233;lin-Cambrioleur-(Roublard).html&quot; title=&quot;F&#233;lin cambrioleur&quot;&gt;F&#233;lin cambrioleur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;) (MR)&lt;/li&gt;
